"""Explicit optional GET views in the complete original HTML; no browser."""
import json
import subprocess
from pathlib import Path
import pytest

HARNESS = r'''
const fs=require('fs'),vm=require('vm'),assert=require('assert'),crypto=require('crypto');
const mode=process.argv[1],id=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0'),sha=c=>c.repeat(64);let seq=50;
class Element{
constructor(tag='div'){this.tagName=tag;this.children=[];const named={};this.elements=new Proxy([],{get:(a,k)=>k in a?a[k]:(named[k]??=new Element('input'))});this.dataset={};this.textContent='';this.value='';this.hidden=true;this.disabled=false;this.checked=false;this.style={};this.listeners={};}
append(...x){this.children.push(...x)}replaceChildren(...x){this.children=x;this.textContent=''}prepend(...x){this.children.unshift(...x)}reset(){}addEventListener(n,f){(this.listeners[n]??=[]).push(f)}setAttribute(){}removeAttribute(n){delete this[n]}closest(){return null}querySelectorAll(selector){const found=[];for(const e of this.children){if(selector==='input[data-cold-goal]'&&e.dataset?.coldGoal)found.push(e);if(e.querySelectorAll)found.push(...e.querySelectorAll(selector));}return found}scrollIntoView(){}focus(){}select(){}remove(){}get firstElementChild(){return this.children[0]}get options(){return this.children.filter(x=>x.tagName==='option')}get selectedOptions(){return this.options.filter(x=>x.value===this.value)}
}


const owner='owner-b',prep=id(1),caseId=id(2),plan=id(3),group=id(4),r1=id(5),r2=id(6),calls=[],goals=['LOCAL_MATERIAL_PREPARATION','LOCAL_CASE_RESOURCE_ASSOCIATION','LOCAL_INTERNAL_ACCEPTANCE','LOCAL_SYNTHETIC_RECEIPT_ACKNOWLEDGEMENT','LOCAL_SYNTHETIC_COORDINATION_RECORDS','LOCAL_CASE_RECORD_RECHECK'];
const binding={source:'trusted-adopted-plan'},bindhash=crypto.createHash('sha256').update(JSON.stringify(binding)).digest('hex');
const flags={scope:'OWNED_SYNTHETIC_RULE_SIMULATION_V1',governance:'DEVELOPMENT_SIMULATION',formal_review:false,business_publication:false,deployment_enabled:false,qualification_truth:'UNKNOWN',qualification_decision:'NOT_EVALUATED',fact_authenticity:'USER_ASSERTED_UNVERIFIED',case_goal_completed:false};
let wait=false,resume=null;
function rules(){const x={...flags,actor_ref:owner,preparation_id:prep,case_id:caseId,preparation_revision:4,source_sha256:sha('a'),sources:{preparation_id:prep,case_id:caseId,preparation_revision:4,context:{binding_id:'owned-rule',as_of:'2026-10-15T08:00:00Z'},binding:{binding_id:'owned-rule',epoch:2,content_sha256:sha('b')},purpose_status:{state:'CURRENT',issues:[]},selected_facts:[{field:'region',assertion_id:id(11)}]},result:{...flags,synthetic_simulated_condition_truth:mode==='rules_false'?'FALSE':mode==='rules_unknown'?'UNKNOWN':'TRUE',conditions:[{kind:'EQ',field:'region',truth:mode==='rules_false'?'FALSE':mode==='rules_unknown'?'UNKNOWN':'TRUE',reason:mode==='rules_unknown'?'CONFLICTING_EVIDENCE':'SYNTHETIC_MECHANICAL_MATCH',evidence:[{id:id(11),revision:2,fingerprint:sha('c')},{id:id(12),revision:1,fingerprint:sha('d')}]}]},history:[]};if(mode==='rules_wrong_subject')x.actor_ref='another-owner';if(mode==='rules_formal')x.formal_review=true;if(mode==='rules_qualified')x.result.qualification_truth='TRUE';if(mode==='rules_bad_source')x.sources.context.binding_id='different';if(mode==='rules_xss')x.result.conditions[0].reason='<img src=x onerror=bad>';return x;}
function alternatives(){const x={scope:'SYNTHETIC_V4_SAME_RESOURCE_TIME_ALTERNATIVES',actor_ref:owner,preparation_id:prep,case_id:caseId,preparation_revision:4,plan_id:plan,plan_revision:1,link_revision:1,original_combination_id:group,source_binding_sha256:bindhash,source_sha256:sha('a'),required_goals:goals,coverage:'SAME_SELECTED_RESOURCES_SEARCH_WINDOW_GRID_ONLY',business_writes:false,authorization_writes:false,automatic_execution:false,old_occupancy_released:false,case_goal_completed:false,search:{search_from:'2026-10-15T08:00:00Z',search_until:'2026-10-15T10:00:00Z'},state:mode==='time_blocked'?'BLOCKED':mode==='time_empty'?'NO_SOLUTION':'AVAILABLE',blockers:mode==='time_blocked'?['OWNER_EXECUTE_REQUIRED']:[],current_issues:['COMBINATION_CANCELLED'],items:[]};if(x.state==='AVAILABLE')x.items=[{starts_at:'2026-10-15T08:00:00Z',ends_at:'2026-10-15T09:00:00Z',option_sha256:sha('e'),members:[r1,r2].map((resource_id,n)=>({resource_id,expected_revision:2,quantity:n+1,starts_at:'2026-10-15T08:00:00Z',ends_at:'2026-10-15T09:00:00Z',buffer_seconds:0,occupied_peak:0}))}];if(mode==='time_subminute'){x.items[0].ends_at='2026-10-15T09:00:30Z';x.items[0].members.forEach(m=>m.ends_at=x.items[0].ends_at);}if(mode==='time_wrong_resource')x.items[0].members[1].resource_id=id(99);if(mode==='time_wrong_binding')x.source_binding_sha256=sha('f');if(mode==='time_omitted_goal')x.required_goals=goals.slice(1);return x;}
function recovered(){const key='original_key',kind=mode.includes('combo')?'COMBINATION':mode.includes('link')?'LINK':'HOLD',x={scope:'SYNTHETIC_V4_SAME_RESOURCE_TIME_ALTERNATIVES',actor_ref:owner,request_key:key,status:mode==='recovery_unknown'?'NOT_OBSERVED':'COMMITTED',historical_only:true,automatically_replayed:false,business_writes:false,not_observed_does_not_prove_uncommitted:true,fingerprint:sha('a')};if(kind==='HOLD'){x.hold={id:id(13),state:'CONFIRMED'};x.receipt={scope:'SYNTHETIC_LOCAL_RESOURCE_HOLD_ONLY',hold_id:id(13),action:'CONFIRM'};}else if(kind==='COMBINATION'){x.combination={id:group,state:'CANCELLED'};x.receipt={scope:'LOCAL_SYNTHETIC_TWO_RESOURCE_COMBINATION_ONLY',combination_id:group,action:'CANCEL'};}else{x.record={id:id(14),preparation_id:prep,case_id:caseId,actor_id:owner,request_key:key,fingerprint:sha('a'),revision:1};}if(mode==='recovery_bad_key')x.request_key='wrong';if(mode==='recovery_bad_receipt')x.receipt.hold_id=id(99);return x;}
async function fetchAPI(path,options={}){calls.push({path,options});if(wait)await new Promise(resolve=>resume=resolve);if(mode==='disabled')return {ok:false,status:403,json:async()=>({})};let body;if(path.includes('/synthetic-rule-readiness?'))body=rules();else if(path.includes('/resource-time-alternatives?'))body=alternatives();else if(path.includes('/recovery/'))body=recovered();else throw Error('unexpected '+path);return {ok:true,status:200,json:async()=>body};}
function page(seed={}){const elements=new Map(),get=id=>{if(!elements.has(id)){const e=new Element();e.id=id;elements.set(id,e)}return elements.get(id)},store={...seed};const storage=new Proxy({getItem:n=>store[n]??null,setItem:(n,v)=>store[n]=v,removeItem:n=>delete store[n]},{ownKeys:()=>Object.keys(store),getOwnPropertyDescriptor:()=>({enumerable:true,configurable:true})});get('run-access-valid-until').parentElement={firstChild:{textContent:''}};
const ctx=vm.createContext({console,Date,JSON,Map,Set,WeakMap,Number,String,Error,encodeURIComponent,URLSearchParams,structuredClone,TextEncoder,Option:function(t,v){const x=new Element('option');x.textContent=t;x.value=v;return x},crypto:{randomUUID:()=>id(seq++),subtle:require('crypto').webcrypto.subtle},localStorage:storage,setTimeout:()=>1,clearTimeout:()=>{},location:{search:''},document:{getElementById:get,createElement:t=>new Element(t),querySelectorAll:()=>[],body:new Element('body'),addEventListener(){}},window:{addEventListener(){}},fetch:fetchAPI});
vm.runInContext(fs.readFileSync('src/parkweave/web.html','utf8').match(/<script[^>]*>([\s\S]*?)<\/script>/)[1],ctx);return {get,read:s=>vm.runInContext(s,ctx),snapshot:()=>({...store})};}


function texts(e){return [e.textContent,...e.children.flatMap(texts)].join('\n');}
function context(p){p.get('token').value='SYNTHETIC_UI_SESSION';p.read(`prepRole='enterprise_operator';preparationId=${JSON.stringify(prep)};preparationView={preparation:{id:${JSON.stringify(prep)},owner_id:${JSON.stringify(owner)},case_id:${JSON.stringify(caseId)},revision:4}};preparationContext=prepContext();servicePlanView={preparation_id:${JSON.stringify(prep)},case_id:${JSON.stringify(caseId)},preparation_revision:4,plan_id:${JSON.stringify(plan)},revision:1,binding:${JSON.stringify(binding)},required_goals:${JSON.stringify(goals)}};caseResourceView={case_id:${JSON.stringify(caseId)},preparation_revision:4,link_revision:1,current:{combination:{id:${JSON.stringify(group)},members:[{resource_id:${JSON.stringify(r1)}},{resource_id:${JSON.stringify(r2)}}]}}};`);p.get('simulation-binding').value='owned-rule';p.get('simulation-as-of').value='2026-10-15T08:00';p.get('case-time-from').value='2026-10-15T08:00';p.get('case-time-until').value='2026-10-15T10:00';}
(async()=>{const p=page();assert.equal(calls.length,0);context(p);if(mode.startsWith('recovery_')){p.get('case-resource-recovery-kind').value=mode.includes('combo')?'COMBINATION':mode.includes('link')?'LINK':'HOLD';p.get('case-resource-recovery-key').value='original_key';if(mode==='recovery_pending_exact'||mode==='recovery_pending_other')p.read('entryWriteRequests.set("unknown",{token:"Bearer SYNTHETIC_UI_SESSION",key:'+JSON.stringify(mode==='recovery_pending_exact'?'original_key':'different_key')+',path:"/api/synthetic-resources/'+r1+'/holds"})');await p.get('case-resource-recovery-read').onclick();const text=texts(p.get('case-resource-recovery-result'));assert(text.includes(mode==='recovery_pending_other'?'请先核对':mode==='recovery_unknown'?'NOT_OBSERVED':mode==='recovery_bad_key'?'无法核实':mode==='recovery_bad_receipt'?'不匹配':'COMMITTED'));}
else if(mode.startsWith('time_')){await p.get('case-time-read').onclick();if(['time_wrong_resource','time_wrong_binding','time_omitted_goal'].includes(mode)){assert.equal(p.read('boundedCaseReadView'),null);}else{const text=texts(p.get('case-time-result'));assert(text.includes(mode==='time_blocked'?'BLOCKED':mode==='time_empty'?'NO_SOLUTION':'AVAILABLE'));if(mode==='time_prefill'||mode==='time_missing_catalog'||mode==='time_stale'||mode==='time_subminute'){if(mode!=='time_missing_catalog'){p.get('resource-form').hidden=false;const o=new Element('option');o.value=r2;o.dataset.resourceRevision='2';p.get('resource-select').append(o);}if(mode==='time_stale')p.read('servicePlanView.revision=2');const before=calls.length,card=p.get('case-time-result').children.find(e=>e.tagName==='article');await card.children.filter(e=>e.tagName==='button')[1].onclick();assert.equal(calls.length,before);if(mode==='time_prefill'){assert.equal(p.get('resource-select').value,r2);assert.equal(p.get('resource-quantity').value,'2');assert(p.get('resource-hold').disabled);assert.equal(p.get('resource-purpose').value,'');assert.equal(p.get('resource-start').value,'2026-10-15T08:00');}else assert(p.get('case-time-status').textContent.includes(mode==='time_stale'?'变化':mode==='time_subminute'?'整分钟':'当前目录'));}}}
else if(mode==='late_token'||mode==='late_input'){wait=true;const read=p.get('simulation-rule-read').onclick();while(!resume)await new Promise(r=>setImmediate(r));if(mode==='late_token')p.get('token').value='OTHER';else p.read('clearBoundedCaseReads()');resume();await read;assert.equal(p.get('simulation-rule-result').children.length,0);}
else{await p.get('simulation-rule-read').onclick();if(['rules_wrong_subject','rules_formal','rules_qualified','rules_bad_source','disabled'].includes(mode))assert.equal(p.get('simulation-rule-result').children.length,0);else{const text=texts(p.get('simulation-rule-result'));assert(text.includes(mode==='rules_false'?'FALSE':mode==='rules_unknown'?'UNKNOWN':'TRUE'));assert(text.includes('资格 UNKNOWN'));assert(text.includes('未经真实性核验'));assert(text.includes(id(11)));if(mode==='rules_xss')assert(text.includes('<img src=x onerror=bad>'));}}
assert(calls.every(c=>c.options.method==='GET'));assert.deepEqual(p.snapshot(),{});console.log(JSON.stringify({result:'PASS',mode,completeOriginalHTML:true,http:calls.length,posts:0}));})().catch(e=>{console.error(e.stack);process.exitCode=1});
'''


@pytest.mark.parametrize('mode', ['rules_true','rules_false','rules_unknown','rules_wrong_subject','rules_formal','rules_qualified','rules_bad_source','rules_xss','disabled','late_token','late_input','time_available','time_blocked','time_empty','time_prefill','time_missing_catalog','time_stale','time_subminute','time_wrong_resource','time_wrong_binding','time_omitted_goal','recovery_pending_exact','recovery_pending_other','recovery_hold','recovery_combo','recovery_link','recovery_unknown','recovery_bad_key','recovery_bad_receipt'])
def test_complete_html_optional_read_only_views(mode):
    root=Path(__file__).resolve().parents[1]
    completed=subprocess.run(['node','-e',HARNESS,mode],cwd=root,capture_output=True,text=True,timeout=25)
    assert completed.returncode==0,completed.stdout+completed.stderr
    result=json.loads(completed.stdout.strip().splitlines()[-1])
    assert result['result']=='PASS' and result['completeOriginalHTML'] is True and result['posts']==0
